sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float fadeLeft;
uniform float fadeRight;
uniform float fadeTop;
uniform float fadeBottom;
uniform float curve;
uniform float inset;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float l = fadeLeft < 0.5 ? 1.0 : saturate((coord.x - inset) / fadeLeft);
    float r = fadeRight < 0.5 ? 1.0 : saturate((size.x - inset - coord.x) / fadeRight);
    float t = fadeTop < 0.5 ? 1.0 : saturate((coord.y - inset) / fadeTop);
    float b = fadeBottom < 0.5 ? 1.0 : saturate((size.y - inset - coord.y) / fadeBottom);
    float m = pow(l * r * t * b, curve);
    m *= step(inset, coord.x) * step(coord.x, size.x - inset) * step(inset, coord.y) * step(coord.y, size.y - inset);
    return fin(c, c * m, opacity);
}
